/**
 * Parula 컬러의 기준이 되는 9가지 HEX 포인트
 */
const PARULA_BASE = [
  '#352a87',
  '#0363e1',
  '#1485d4',
  '#06a7c6',
  '#38b99e',
  '#92bf73',
  '#d9ba56',
  '#fcd225',
  '#f9fb0e',
];

/**
 * Jet 컬러의 기준 지점 (0.0 ~ 1.0 구간별 RGB 값)
 */
const JET_BASE = [
  { pos: 0.0, r: 0, g: 0, b: 143 }, // Dark Blue
  { pos: 0.1, r: 0, g: 0, b: 255 }, // Blue
  { pos: 0.3, r: 0, g: 255, b: 255 }, // Cyan
  { pos: 0.5, r: 127, g: 255, b: 127 }, // Green-ish Yellow
  { pos: 0.7, r: 255, g: 255, b: 0 }, // Yellow
  { pos: 0.9, r: 255, g: 0, b: 0 }, // Red
  { pos: 1.0, r: 127, g: 0, b: 0 }, // Dark Red
];

/**
 * HEX 코드를 RGB 객체로 변환
 */
const hexToRgb = (hex) => {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result
    ? {
        r: parseInt(result[1], 16),
        g: parseInt(result[2], 16),
        b: parseInt(result[3], 16),
      }
    : null;
};

/**
 * Turbo 컬러의 핵심 앵커 포인트 (0.0 ~ 1.0 구간별 RGB)
 * Jet보다 더 세밀한 구간 설정을 통해 부드러운 곡선을 흉내냅니다.
 */
const TURBO_BASE = [
  { pos: 0.0, r: 48, g: 18, b: 59 },
  { pos: 0.1, r: 66, g: 77, b: 178 },
  { pos: 0.2, r: 70, g: 130, b: 249 },
  { pos: 0.3, r: 43, g: 181, b: 226 },
  { pos: 0.4, r: 27, g: 221, b: 165 },
  { pos: 0.5, r: 106, g: 241, b: 84 },
  { pos: 0.6, r: 185, g: 235, b: 53 },
  { pos: 0.7, r: 242, g: 201, b: 57 },
  { pos: 0.8, r: 254, g: 139, b: 44 },
  { pos: 0.9, r: 227, g: 68, b: 12 },
  { pos: 1.0, r: 144, g: 12, b: 2 },
];

/**
 * RGB를 HEX 코드로 변환
 */
const rgbToHex = (r, g, b) =>
  '#' + [r, g, b].map((x) => Math.round(x).toString(16).padStart(2, '0')).join('');

/**
 * stepCount만큼의 Parula 컬러 리스트를 반환하는 함수
 */
export const generateBaseColors = (Base, stepCount) => {
  if (stepCount <= 1) return [Base[0]];

  const colors = [];
  const baseRgb = Base.map(hexToRgb);
  for (let i = 0; i < stepCount; i++) {
    // 0부터 1 사이의 진행도
    const t = i / (stepCount - 1);

    // 현재 단계가 위치한 baseRgb의 인덱스 구간 계산
    const scaledT = t * (baseRgb.length - 1);
    const idx1 = Math.floor(scaledT);
    const idx2 = Math.min(idx1 + 1, baseRgb.length - 1);

    // 구간 내에서의 상세 비율
    const localT = scaledT - idx1;

    const c1 = baseRgb[idx1];
    const c2 = baseRgb[idx2];

    // RGB 선형 보간 (Linear Interpolation)
    const r = c1.r + (c2.r - c1.r) * localT;
    const g = c1.g + (c2.g - c1.g) * localT;
    const b = c1.b + (c2.b - c1.b) * localT;

    colors.push(rgbToHex(r, g, b));
  }

  return colors;
};

/**
 * stepCount만큼의 Parula 컬러 리스트를 반환하는 함수
 */
export const generateParulaColors = (stepCount) => {
  if (stepCount <= 1) return [PARULA_BASE[0]];

  const colors = [];
  const baseRgb = PARULA_BASE.map(hexToRgb);

  for (let i = 0; i < stepCount; i++) {
    // 0부터 1 사이의 진행도
    const t = i / (stepCount - 1);

    // 현재 단계가 위치한 baseRgb의 인덱스 구간 계산
    const scaledT = t * (baseRgb.length - 1);
    const idx1 = Math.floor(scaledT);
    const idx2 = Math.min(idx1 + 1, baseRgb.length - 1);

    // 구간 내에서의 상세 비율
    const localT = scaledT - idx1;

    const c1 = baseRgb[idx1];
    const c2 = baseRgb[idx2];

    // RGB 선형 보간 (Linear Interpolation)
    const r = c1.r + (c2.r - c1.r) * localT;
    const g = c1.g + (c2.g - c1.g) * localT;
    const b = c1.b + (c2.b - c1.b) * localT;

    colors.push(rgbToHex(r, g, b));
  }

  return colors;
};

/**
 * stepCount 만큼 Jet Gradient 색상 리스트를 생성하여 반환
 */
export const generateJetColors = (stepCount) => {
  if (stepCount <= 1) return [rgbToHex(JET_BASE[0].r, JET_BASE[0].g, JET_BASE[0].b)];

  const colors = [];

  for (let i = 0; i < stepCount; i++) {
    const t = i / (stepCount - 1); // 0.0 ~ 1.0 진행도

    // 현재 t값이 위치한 구간 찾기
    let idx = 0;
    while (idx < JET_BASE.length - 1 && t > JET_BASE[idx + 1].pos) {
      idx++;
    }

    const start = JET_BASE[idx];
    const end = JET_BASE[idx + 1];

    // 해당 구간 내에서의 보간 비율 계산
    const range = end.pos - start.pos;
    const localT = (t - start.pos) / range;

    // 선형 보간 (Lerp)
    const r = start.r + (end.r - start.r) * localT;
    const g = start.g + (end.g - start.g) * localT;
    const b = start.b + (end.b - start.b) * localT;

    colors.push(rgbToHex(r, g, b));
  }

  return colors;
};

/**
 * stepCount 만큼 Turbo Gradient 색상 리스트를 생성하여 반환
 */
export const generateTurboColors = (stepCount) => {
  if (stepCount <= 1) return [rgbToHex(TURBO_BASE[0].r, TURBO_BASE[0].g, TURBO_BASE[0].b)];

  const colors = [];

  for (let i = 0; i < stepCount; i++) {
    const t = i / (stepCount - 1);

    // 현재 t값이 위치한 구간 찾기
    let idx = 0;
    while (idx < TURBO_BASE.length - 1 && t > TURBO_BASE[idx + 1].pos) {
      idx++;
    }

    const start = TURBO_BASE[idx];
    const end = TURBO_BASE[idx + 1];

    // 구간 내 보간 비율
    const range = end.pos - start.pos;
    const localT = (t - start.pos) / range;

    // 선형 보간
    const r = start.r + (end.r - start.r) * localT;
    const g = start.g + (end.g - start.g) * localT;
    const b = start.b + (end.b - start.b) * localT;

    colors.push(rgbToHex(r, g, b));
  }

  return colors;
};

export const generateBinColors = () => {
  const hexColors = [];
  const totalCount = 999;

  // HSL을 HexCode로 변환하는 내부 함수
  const hslToHex = (h, s, l) => {
    l /= 100;
    const a = (s * Math.min(l, 1 - l)) / 100;
    const f = (n) => {
      const k = (n + h / 30) % 12;
      const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color)
        .toString(16)
        .padStart(2, '0');
    };
    return `#${f(0)}${f(8)}${f(4)}`.toUpperCase();
  };

  for (let i = 0; i < totalCount; i++) {
    // 1. 황금비(137.5도)를 사용하여 색상을 고르게 분산
    let hue = (i * 137.508) % 360;

    // 2. 파란색 구간(190도 ~ 270도) 제외 및 조정
    // 190~270도 사이의 값이 나오면 해당 구간을 건너뛰도록 보정
    if (hue >= 190 && hue <= 270) {
      // 파란색 구간에 걸리면 80도를 더해 보라색/빨간색 구간으로 점프
      hue = (hue + 80) % 360;
    }

    // 3. 채도(Saturation)와 명도(Lightness)를 다변화하여 999개 구분력 확보
    // 단순히 색상만 바꾸면 999개를 구분하기 힘들므로 명도와 채도에 미세한 변화를 줌
    const saturation = 65 + (i % 15); // 65% ~ 80%
    const lightness = 45 + (i % 20); // 45% ~ 65%

    hexColors.push(hslToHex(hue, saturation, lightness));
  }

  return hexColors;
};
