import React, { useState } from 'react';
import SearchMonitoring from './Search-Monitoring';
import GalleryChart from './GalleryChart';
import Output from './Output';
//import SearchMonitoring from './Search-Mobile';
//import GalleryChart from './Gallery-Mobile';
//import Output from './Output-Mobile';
import { generateDatas } from '../utils/DataGenerator';

const LayoutMonitoring = () => {
  const [data, setData] = useState([]);
  const [chartType, setChartType] = useState('line');
  const [activeTab, setActiveTab] = useState('search');
  const [gridCols, setGridCols] = useState(4);

  const handleRun = (selectedParams) => {
    const newData = generateDatas(selectedParams);
    setChartType(selectedParams.chartType);
    setGridCols(selectedParams.chartCols);
    setData(newData);
    setActiveTab('chart');
  };

  return (
    <div
      style={{
        display: 'flex', // Flexbox 적용
        flexDirection: 'column', // 세로 방향 배치
        height: '93vh', // 화면 전체 높이 고정 (브라우저 스크롤 방지)
        padding: '0 15px',
        fontFamily: 'Arial',
        boxSizing: 'border-box',
        overflow: 'hidden', // 부모의 넘침 방지
      }}
    >
      {/* 탭 메뉴 영역: Sticky 대신 상단 고정 */}
      <div
        style={{
          display: 'flex',
          backgroundColor: '#fff',
          zIndex: 100,
          marginTop: '3px',
          borderBottom: '2px solid #ddd',
          flexShrink: 0, // 탭 영역이 줄어들지 않도록 설정
        }}
      >
        <button onClick={() => setActiveTab('search')} style={tabStyle(activeTab === 'search')}>
          🔍 Search
        </button>
        <button onClick={() => setActiveTab('chart')} style={tabStyle(activeTab === 'chart')}>
          📊 Chart
        </button>
        <button onClick={() => setActiveTab('output')} style={tabStyle(activeTab === 'output')}>
          📋 Data
        </button>
      </div>

      {/* 탭 콘텐츠 영역: 여기가 실제 스크롤되는 공간 */}
      <div
        style={{
          flex: 1, // 남은 화면 공간을 모두 차지
          overflowY: 'auto', // 내용이 많아지면 내부 스크롤 발생
          padding: '15px 0',
          position: 'relative',
        }}
      >
        {/* Search 탭 내용 */}
        <div style={{ display: activeTab === 'search' ? 'block' : 'none' }}>
          <SearchMonitoring onRun={handleRun} />
        </div>

        {/* Chart 탭 내용 */}
        <div style={{ display: activeTab === 'chart' ? 'block' : 'none' }}>
          {data.length > 0 ? (
            <GalleryChart data={data} type={chartType} cols={gridCols} />
          ) : (
            <div style={emptyStyle}>조회 데이터가 없습니다.</div>
          )}
        </div>

        {/* Data 탭 내용 */}
        <div style={{ display: activeTab === 'output' ? 'block' : 'none' }}>
          {data.length > 0 ? (
            <Output data={data} />
          ) : (
            <div style={emptyStyle}>조회 데이터가 없습니다.</div>
          )}
        </div>
      </div>
    </div>
  );
};

// --- 기존 스타일 유지 (tabStyle 일부 수정) ---
const tabStyle = (isActive) => ({
  padding: '8px 18px',
  cursor: 'pointer',
  background: isActive ? '#007bff' : '#f8f9fa',
  color: isActive ? '#fff' : '#333',
  border: 'none',
  borderBottom: isActive ? '3px solid #0056b3' : 'none',
  fontSize: '13px',
  fontWeight: 'bold',
  transition: '0.3s',
  marginRight: '5px',
  borderRadius: '5px 5px 0 0',
  lineHeight: '1.2',
});

const emptyStyle = {
  textAlign: 'center',
  padding: '100px',
  color: '#888',
  backgroundColor: '#f9f9f9',
  borderRadius: '10px',
};

export default LayoutMonitoring;
