import React, { useMemo } from 'react';
import ReactECharts from 'echarts-for-react';

const GradientMap = ({ params, data, type = 'shot', colors }) => {
  const defaultColors = [
    '#352a87',
    '#0363e1',
    '#1485d4',
    '#06a7c6',
    '#38b99e',
    '#92bf73',
    '#d9ba56',
    '#f9fb0e',
  ];
  const finalColors = colors && colors.length > 0 ? colors : defaultColors;

  const { chartData, xRange, yRange, maxX, maxY, dynamicMin, dynamicMax } = useMemo(() => {
    if (!data || data.length === 0) {
      return {
        chartData: [],
        xRange: [0, 1],
        yRange: [0, 1],
        maxX: 1,
        maxY: 1,
        dynamicMin: 0,
        dynamicMax: 100,
      };
    }

    // 1. CD Value의 실제 Min/Max 추출
    const values = data.map((d) => d.cdvalue).filter((v) => v !== null && v !== undefined);
    let minVal = Math.min(...values);
    let maxVal = Math.max(...values);

    // 모든 값이 동일할 경우 그라데이션 표현을 위해 범위를 강제로 넓힘
    if (minVal === maxVal) {
      minVal -= 1;
      maxVal += 1;
    }

    // 2. 좌표 데이터 포맷팅
    const formattedData = data.map((item) => {
      const val = item.cdvalue ?? 0;
      return type === 'chip'
        ? [item.chipx ?? 0, item.chipy ?? 0, val]
        : [item.shotx ?? 0, item.shoty ?? 0, val];
    });

    // 3. 맵 사이즈 및 중앙 배치 계산
    let mX = (params.dieSizeX + params.scribeSize) * params.shotxCount;
    let mY = (params.dieSizeY + params.scribeSize) * params.shotyCount;
    if (type === 'chip') {
      mX = params.dieSizeX;
      mY = params.dieSizeY;
    }

    const diff = Math.abs(mX - mY) / 2;
    let xMin = 0,
      xMax = mX,
      yMin = 0,
      yMax = mY;
    if (mX > mY) {
      yMin -= diff;
      yMax += diff;
    } else if (mY > mX) {
      xMin -= diff;
      xMax += diff;
    }

    return {
      chartData: formattedData,
      xRange: [xMin, xMax],
      yRange: [yMin, yMax],
      maxX: mX,
      maxY: mY,
      dynamicMin: minVal,
      dynamicMax: maxVal,
    };
  }, [params, data, type]);

  if (!chartData.length) return <div style={{ color: '#ccc', fontSize: '10px' }}>No Data</div>;

  const option = {
    tooltip: {
      trigger: 'item',
      formatter: (p) => {
        const label = type === 'chip' ? 'Chip' : 'Shot';
        return `${label} X: ${p.value[0].toFixed(2)}<br/>${label} Y: ${p.value[1].toFixed(2)}<br/><b>CD: ${p.value[2].toFixed(3)}</b>`;
      },
    },
    visualMap: {
      show: false,
      min: dynamicMin, // 계산된 실제 최소값 적용
      max: dynamicMax, // 계산된 실제 최대값 적용
      dimension: 2,
      inRange: { color: finalColors },
    },
    grid: { top: 10, left: 10, right: 10, bottom: 10 },
    xAxis: { type: 'value', min: xRange[0], max: xRange[1], show: false },
    yAxis: { type: 'value', min: yRange[0], max: yRange[1], show: false },
    series: [
      {
        type: 'scatter',
        data: chartData,
        symbolSize: 6,
        itemStyle: { opacity: 0.9 },
        markArea: {
          silent: true,
          itemStyle: {
            color: 'transparent',
            borderWidth: 1.5,
            borderColor: '#475569',
            borderType: 'solid',
          },
          data: [[{ coord: [0, 0] }, { coord: [maxX, maxY] }]],
        },
      },
    ],
  };

  return <ReactECharts option={option} style={{ height: '100%', width: '100%' }} />;
};

export default GradientMap;
