import React, { useMemo, useState } from 'react';
import ReactECharts from 'echarts-for-react';

const GalleryChart = ({ data, type, cols }) => {
  const [expandedCat, setExpandedCat] = useState(null);
  const [legendPos, setLegendPos] = useState('bottom');
  const [tooltipMode, setTooltipMode] = useState('item');
  const [selectedCols, setSelectedCols] = useState(['lot_id', 'wafer_id', 'value', 'tkout_time']);
  const [isColModalOpen, setIsColModalOpen] = useState(false);

  // 🎨 50개 이상의 추천 색상 팔레트 생성 로직
  const chartColors = useMemo(() => {
    const basePalette = [
      '#5470c6',
      '#91cc75',
      '#fac858',
      '#ee6666',
      '#73c0de',
      '#3ba272',
      '#fc8452',
      '#9a60b4',
      '#ea7ccc',
      '#51689b',
      '#ce5c5c',
      '#fbc357',
      '#8fbf8f',
      '#659d84',
      '#fb8e6a',
      '#c77288',
      '#7874a3',
      '#6890ba',
      '#49c8b8',
      '#64bc8e',
    ];

    // 50개를 채우기 위해 채도와 명도를 조절한 변형 색상 추가
    const extendedPalette = [...basePalette];
    const variations = [
      (c) => c + 'CC', // 80% 투명도
      (c) => c.replace('5', '7').replace('8', 'a'), // 약간의 색조 변형
    ];

    let i = 0;
    while (extendedPalette.length < 50) {
      extendedPalette.push(basePalette[i % basePalette.length] + 'AA'); // 투명도 변형으로 개수 확보
      i++;
    }
    return extendedPalette;
  }, []);

  const allColumns = useMemo(() => {
    if (data.length === 0) return [];
    return Object.keys(data[0]);
  }, [data]);

  const grouped = useMemo(() => {
    return data.reduce((acc, curr) => {
      const catName = `${curr.step} / ${curr.y1item}`;
      if (!acc[catName]) acc[catName] = [];
      acc[catName].push(curr);
      return acc;
    }, {});
  }, [data]);

  const handleDoubleClick = (cat) => {
    setExpandedCat((prev) => (prev === cat ? null : cat));
    if (!expandedCat) setTooltipMode('item');
  };

  const handleColToggle = (col) => {
    setSelectedCols((prev) =>
      prev.includes(col) ? prev.filter((c) => c !== col) : [...prev, col],
    );
  };

  const getOption = (cat, items, isExpanded) => {
    const partids = [...new Set(items.map((i) => i.partid))];
    const sortedItems = [...items].sort((a, b) => new Date(a.tkout_time) - new Date(b.tkout_time));
    const xAxisData = [...new Set(sortedItems.map((i) => i.tkout_time))];
    const currentPos = isExpanded ? legendPos : 'bottom';
    const isVertical = currentPos === 'left' || currentPos === 'right';

    // --- 데이터 및 시리즈 설정 ---
    let series = [];
    if (type === 'box') {
      // 🎨 Boxplot을 partid별 개별 시리즈로 생성하여 색상 적용
      series = partids.map((partid, idx) => {
        const values = items
          .filter((i) => i.partid === partid)
          .map((i) => i.value)
          .sort((a, b) => a - b);

        const color = chartColors[idx % chartColors.length];
        const boxData =
          values.length === 0
            ? [0, 0, 0, 0, 0]
            : [
                values[0],
                values[Math.floor(values.length * 0.25)],
                values[Math.floor(values.length * 0.5)],
                values[Math.floor(values.length * 0.75)],
                values[values.length - 1],
              ];

        return {
          name: partid,
          type: 'boxplot',
          // boxplot 데이터는 [ [min, q1, med, q3, max] ] 형태로 들어가야 함
          data: [boxData],
          itemStyle: {
            borderColor: color,
            borderWidth: 2,
            color: color + '33', // 박스 내부를 연한 투명색으로 채움 (추천)
          },
        };
      });
    } else {
      series = partids.map((partid, idx) => ({
        name: partid,
        type: type === 'scatter' ? 'scatter' : 'line',
        // 🎨 확보한 50개 색상을 인덱스에 맞춰 적용
        itemStyle: { color: chartColors[idx % chartColors.length] },
        lineStyle: { color: chartColors[idx % chartColors.length], width: 2 },
        data: xAxisData.map((time) => {
          const found = items.find((i) => i.partid === partid && i.tkout_time === time);
          return found ? found.value : null;
        }),
        smooth: type === 'line',
        symbolSize: isExpanded ? 8 : 4,
        connectNulls: true,
      }));
    }

    // --- 통합 툴팁 설정 ---
    const tooltipConfig = {
      show: true,
      confine: true,
      trigger: 'item', // Boxplot은 item 트리거가 정확함
      axisPointer: { type: 'cross' },
      formatter: (params) => {
        const p = Array.isArray(params) ? params[0] : params;

        // 1. Boxplot 툴팁
        if (type === 'box') {
          // p.data는 [index, min, q1, med, q3, max] 구조임
          return `
            <div style="font-weight:bold; border-bottom:1px solid #ccc; margin-bottom:5px; color:${p.color}">
              ${p.seriesName}
            </div>
            <div style="font-size:12px;">Max: <span style="float:right; font-weight:bold;">${p.data[5]}</span></div>
            <div style="font-size:12px;">Q3: <span style="float:right; font-weight:bold;">${p.data[4]}</span></div>
            <div style="font-size:12px;">Median: <span style="float:right; font-weight:bold;">${p.data[3]}</span></div>
            <div style="font-size:12px;">Q1: <span style="float:right; font-weight:bold;">${p.data[2]}</span></div>
            <div style="font-size:12px;">Min: <span style="float:right; font-weight:bold;">${p.data[1]}</span></div>
                      `;
        }
        // 2. Point 상세 툴팁
        if (isExpanded && tooltipMode === 'item') {
          const originalItem = items.find(
            (i) => i.partid === p.seriesName && i.tkout_time === p.name,
          );
          if (!originalItem) return `${p.name}<br/>Value: ${p.value}`;

          let res = `<div style="font-weight:bold; border-bottom:1px solid #ccc; margin-bottom:5px;">${p.seriesName}</div>`;
          selectedCols.forEach((col) => {
            res += `<div style="font-size:12px;">${col}: <span style="float:right; margin-left:10px; font-weight:bold;">${originalItem[col] ?? '-'}</span></div>`;
          });
          return res;
        }
        return undefined;
      },
    };

    return {
      color: chartColors,
      title: {
        text: cat,
        left: 'center',
        top: '2%',
        textStyle: { fontSize: isExpanded ? 16 : 12 },
      },
      tooltip: tooltipConfig,
      legend: {
        show: true,
        type: 'scroll',
        orient: isVertical ? 'vertical' : 'horizontal',
        bottom: currentPos === 'bottom' ? 5 : 'auto',
        left: currentPos === 'left' ? 10 : currentPos === 'right' ? 'auto' : 'center',
      },
      grid: {
        top: '15%',
        bottom: currentPos === 'bottom' ? '18%' : '12%',
        left: currentPos === 'left' ? '15%' : '8%',
        right: currentPos === 'right' ? '15%' : '8%',
        containLabel: true,
      },
      xAxis: {
        type: 'category',
        data: type === 'box' ? [''] : xAxisData,
      },
      yAxis: { type: 'value', splitLine: { lineStyle: { type: 'dashed' } } },
      series: series,
    };
  };

  return (
    <div style={{ position: 'relative' }}>
      {/* 컬럼 선택 모달 (툴팁 상세 설정) */}
      {isColModalOpen && (
        <div style={modalOverlayStyle}>
          <div style={modalContentStyle}>
            <h4 style={{ marginTop: 0 }}>Display Columns 설정</h4>
            <div style={columnGridStyle}>
              {allColumns.map((col) => (
                <label key={col} style={checkboxLabelStyle}>
                  <input
                    type="checkbox"
                    checked={selectedCols.includes(col)}
                    onChange={() => handleColToggle(col)}
                  />
                  {col}
                </label>
              ))}
            </div>
            <button onClick={() => setIsColModalOpen(false)} style={modalCloseBtnStyle}>
              적용 및 닫기
            </button>
          </div>
        </div>
      )}

      {/* 확대 보기 오버레이 */}
      {expandedCat && (
        <div style={expandedOverlayStyle} onDoubleClick={() => setExpandedCat(null)}>
          <div style={toolbarStyle}>
            <span style={{ fontWeight: 'bold', fontSize: '1.1rem' }}>{expandedCat} 분석</span>
            <div style={{ display: 'flex', gap: '15px', alignItems: 'center' }}>
              {tooltipMode === 'item' && type !== 'box' && (
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    setIsColModalOpen(true);
                  }}
                  style={colSettingBtnStyle}
                >
                  ⚙ Set Columns ({selectedCols.length})
                </button>
              )}
              <div style={controlGroupStyle}>
                <label style={labelStyle}>Tooltip:</label>
                <select
                  value={tooltipMode}
                  onChange={(e) => setTooltipMode(e.target.value)}
                  style={selectStyle}
                >
                  <option value="item">Point (개별)</option>
                  <option value="axis">X-Axis (전체)</option>
                </select>
              </div>
              <div style={controlGroupStyle}>
                <label style={labelStyle}>Legend:</label>
                <select
                  value={legendPos}
                  onChange={(e) => setLegendPos(e.target.value)}
                  style={selectStyle}
                >
                  <option value="bottom">Bottom</option>
                  <option value="left">Left</option>
                  <option value="right">Right</option>
                </select>
              </div>
              <button onClick={() => setExpandedCat(null)} style={closeBtnStyle}>
                닫기
              </button>
            </div>
          </div>
          <div style={{ flex: 1 }}>
            <ReactECharts
              option={getOption(expandedCat, grouped[expandedCat], true)}
              style={{ height: '100%', width: '100%' }}
              notMerge={true}
            />
          </div>
        </div>
      )}

      {/* 기본 그리드 뷰 */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: `repeat(${cols}, 1fr)`,
          gap: '5px',
          opacity: expandedCat ? 0.2 : 1,
        }}
      >
        {Object.entries(grouped).map(([cat, items]) => (
          <div key={cat} onDoubleClick={() => handleDoubleClick(cat)} style={cardStyle}>
            <ReactECharts
              option={getOption(cat, items, false)}
              style={{ height: '100%', width: '100%' }}
              notMerge={true}
            />
          </div>
        ))}
      </div>
    </div>
  );
};

// --- 스타일 객체 (생략 없이 유지) ---
const modalOverlayStyle = {
  position: 'fixed',
  top: 0,
  left: 0,
  right: 0,
  bottom: 0,
  backgroundColor: 'rgba(0,0,0,0.5)',
  zIndex: 2000,
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
};
const modalContentStyle = {
  backgroundColor: '#fff',
  padding: '25px',
  borderRadius: '12px',
  width: '400px',
  boxShadow: '0 10px 25px rgba(0,0,0,0.2)',
};
const columnGridStyle = {
  display: 'grid',
  gridTemplateColumns: '1fr 1fr',
  gap: '10px',
  maxHeight: '300px',
  overflowY: 'auto',
  margin: '15px 0',
  padding: '10px',
  border: '1px solid #eee',
  borderRadius: '6px',
};
const checkboxLabelStyle = {
  display: 'flex',
  alignItems: 'center',
  gap: '8px',
  fontSize: '13px',
  cursor: 'pointer',
};
const modalCloseBtnStyle = {
  width: '100%',
  padding: '10px',
  backgroundColor: '#007bff',
  color: '#fff',
  border: 'none',
  borderRadius: '6px',
  cursor: 'pointer',
};
const expandedOverlayStyle = {
  position: 'fixed',
  top: '20px',
  left: '20px',
  right: '20px',
  bottom: '20px',
  zIndex: 1000,
  backgroundColor: '#fff',
  padding: '20px',
  boxShadow: '0 0 30px rgba(0,0,0,0.3)',
  borderRadius: '12px',
  display: 'flex',
  flexDirection: 'column',
};
const toolbarStyle = {
  display: 'flex',
  justifyContent: 'space-between',
  alignItems: 'center',
  marginBottom: '15px',
};
const controlGroupStyle = { display: 'flex', gap: '5px', alignItems: 'center' };
const labelStyle = { fontSize: '12px', color: '#666' };
const selectStyle = {
  padding: '4px 8px',
  borderRadius: '4px',
  border: '1px solid #ccc',
  fontSize: '13px',
};
const cardStyle = {
  border: '1px solid #ddd',
  padding: '10px',
  borderRadius: '8px',
  height: '300px',
  backgroundColor: '#fff',
};
const closeBtnStyle = {
  padding: '6px 15px',
  cursor: 'pointer',
  backgroundColor: '#444',
  color: '#fff',
  border: 'none',
  borderRadius: '4px',
};
const colSettingBtnStyle = {
  padding: '6px 12px',
  cursor: 'pointer',
  backgroundColor: '#f0f7ff',
  color: '#007bff',
  border: '1px solid #007bff',
  borderRadius: '4px',
  fontSize: '12px',
  fontWeight: 'bold',
};

export default GalleryChart;
